import { useEffect, useRef, type ComponentType } from 'react';
import { ReplyChip, type ReplyRef } from './reply';
import { useComposerVariant, type ComposerVariant } from './composer-variant';
import { useAttachments } from './attachments';
import type { ComposerProps as BaseProps, VariantProps } from './composer-kit';
import { PillComposerView } from './variants/pill';
import { BoxComposerView } from './variants/box';
import { PanelComposerView } from './variants/panel';
import { DockComposerView } from './variants/dock';
import { CommandComposerView } from './variants/command';
import { InlineComposerView } from './variants/inline';
import { VoiceComposerView } from './variants/voice';
import { HaloComposerView } from './variants/halo';
import { MediaComposerView } from './variants/media';
import { PaletteComposerView } from './variants/palette';
import { MentionComposerView } from './variants/mention';

/* The template-facing composer: one prop picks among the eleven composers in kit/variants/ (one file each, each
 * also installable alone from the registry). The attachment queue lives here so switching variant keeps the files. */

/* ------------------------------------------------------------------ switch */

const VARIANTS: Record<ComposerVariant, ComponentType<VariantProps>> = {
  pill: PillComposerView,
  box: BoxComposerView,
  panel: PanelComposerView,
  dock: DockComposerView,
  command: CommandComposerView,
  inline: InlineComposerView,
  voice: VoiceComposerView,
  halo: HaloComposerView,
  media: MediaComposerView,
  palette: PaletteComposerView,
  mention: MentionComposerView,
};

export interface ComposerProps extends BaseProps {
  /** The template's own pick, used while the global choice is `auto`. */
  variant?: ComposerVariant;
  /** Always render `variant`, ignoring the global choice (the /composers showcase). */
  lock?: boolean;
  /** The answer being replied to (the engine's `replyTo`): pinned above the composer until the send. */
  reply?: ReplyRef | null;
  /** × on the reply bar, or Esc in an empty field. */
  onClearReply?: () => void;
}

/** Every composer behind one switch: the template's pick, or the global one from the header picker. */
export function Composer({ variant, lock, placeholder = 'Ask me anything', reply, onClearReply, ...rest }: ComposerProps) {
  const global = useComposerVariant(variant ?? 'pill');
  const active = lock && variant ? variant : global;
  const att = useAttachments();
  const V = VARIANTS[active];
  const box = useRef<HTMLDivElement>(null);
  // Sending takes the landed files with the message, as a composer clears its strip on send.
  const onSend = (v: string) => {
    rest.onSend(v);
    att.clear();
  };
  // A new reply puts the caret in the field, ready to write it.
  useEffect(() => {
    if (reply) box.current?.querySelector<HTMLElement>('textarea, input, [contenteditable=true]')?.focus();
  }, [reply?.id]);
  return (
    // One wrapper whether or not a reply is pinned (`contents` without one), so the field never remounts and keeps focus.
    <div
      ref={box}
      className={reply ? 'flex w-full flex-col gap-2' : 'contents'}
      onKeyDownCapture={(e) => {
        if (e.key === 'Escape' && reply && !rest.value && !rest.busy) {
          e.stopPropagation();
          onClearReply?.();
        }
      }}
    >
      {reply && <ReplyChip reply={reply} onClear={() => onClearReply?.()} />}
      <V {...rest} onSend={onSend} placeholder={placeholder} att={att} />
    </div>
  );
}

import { Reply, X } from 'lucide-react';
import { cn } from '@/lib/utils';

/* Reply to an answer: the quote it carries and the bar pinned above the composer while it is written.
 * Its own file so <Composer> (composers.tsx) can show the bar without importing parts.tsx, which imports it,
 * and so the installable `composer` item ships it whole (the engine re-exports ReplyRef from here). */

/** A message quoted by a reply: which one, and the excerpt shown with it. */
export interface ReplyRef {
  id: string;
  text: string;
  /** Who is quoted ("Assistant" when unset): a model name on Model compare, "Report"… */
  label?: string;
}

/** The quote a reply carries: accent bar, reply icon, one truncated line. */
export function Quote({ text, className }: { text: string; className?: string }) {
  return (
    <span className={cn('flex min-w-0 items-center gap-1.5 border-s-2 border-accent-500 ps-2 text-body-2-regular text-text-tertiary', className)}>
      <Reply className="size-3.5 shrink-0" />
      <span className="truncate">{text}</span>
    </span>
  );
}

/** Pinned above the composer while a reply is being written: what it answers, and × to drop it. */
export function ReplyChip({ reply, onClear, className }: { reply: ReplyRef; onClear: () => void; className?: string }) {
  return (
    <div className={cn('animate-in fade-in-0 slide-in-from-bottom-1 flex items-center gap-2 rounded-xl bg-background-tertiary-default py-1.5 ps-2.5 pe-1 duration-200', className)}>
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="text-caption-1-medium text-text-secondary">Replying to {reply.label ?? 'Assistant'}</span>
        <Quote text={reply.text} className="border-s-0 ps-0" />
      </span>
      <button
        type="button"
        aria-label="Cancel reply"
        title="Cancel reply"
        onClick={onClear}
        className="grid size-7 shrink-0 place-items-center rounded-md text-foreground-icon-tertiary transition-[color,background-color,scale] outline-none hover:bg-background-tertiary-hover hover:text-foreground-icon-primary focus-visible:ring-2 focus-visible:ring-border-focus-ring active:scale-90"
      >
        <X className="size-4" />
      </button>
    </div>
  );
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import { storage } from '@/lib/storage';

/* Which composer every template uses. `auto` keeps each template's own pick; any other value swaps the
 * composer everywhere. The choice is saved and shared like the theme: same-origin frames (the gallery's
 * live thumbnails, other tabs) follow it through the storage event, and `?composer=<id>` forces one. */

export const COMPOSER_VARIANTS = [
  { id: 'pill', name: 'Pill', from: 'Single row', hint: 'One row: add, input, model, send' },
  { id: 'box', name: 'Box', from: 'Textarea', hint: 'Growing textarea over an action row' },
  { id: 'panel', name: 'Panel', from: 'Rail', hint: 'Branch, project and context on a rail; attachments, permission mode' },
  { id: 'dock', name: 'Dock', from: 'Floating toolbar', hint: 'Floating glass toolbar with grouped tools' },
  { id: 'command', name: 'Command', from: 'Terminal', hint: 'Monospace prompt, slash commands, key hints' },
  { id: 'inline', name: 'Inline', from: 'Selection bar', hint: 'Compact bar on a selection; edit or ask, Tab / Esc' },
  { id: 'voice', name: 'Voice', from: 'Voice orb', hint: 'Voice-reactive orb, push-to-talk, live transcript' },
  { id: 'halo', name: 'Halo', from: 'Glow rim', hint: 'Glowing rim, typed example prompts, enhance, vanish on send' },
  { id: 'media', name: 'Media', from: 'Image prompt', hint: 'Prompt with aspect, sliders, style and batch' },
  { id: 'palette', name: 'Palette', from: 'Command palette', hint: 'Command palette that hands the query to AI on Tab' },
  { id: 'mention', name: 'Mention', from: 'Mentions', hint: '@ chips for files, people and sources in the text' },
] as const;

export type ComposerVariant = (typeof COMPOSER_VARIANTS)[number]['id'];
/** The five original composers (kit/composers.tsx); the rest live in kit/variants/. */
export type BaseVariant = 'pill' | 'box' | 'panel' | 'dock' | 'command';
export type ComposerChoice = ComposerVariant | 'auto';

const KEY = 'tpl-composer';
const isVariant = (v: string | null): v is ComposerVariant => COMPOSER_VARIANTS.some((x) => x.id === v);

const Ctx = createContext<{ choice: ComposerChoice; setChoice: (c: ComposerChoice) => void }>({ choice: 'auto', setChoice: () => {} });

export function ComposerVariantProvider({ children }: { children: ReactNode }) {
  // A forced `?composer=` wins for the life of the frame: a choice made in another tab must not replace it.
  const [forced] = useState(() => {
    const param = new URLSearchParams(window.location.search).get('composer');
    return isVariant(param) ? param : null;
  });
  const [choice, setState] = useState<ComposerChoice>(() => {
    if (forced) return forced;
    const saved = storage.get(KEY, 'auto');
    return isVariant(saved) ? saved : 'auto';
  });

  useEffect(() => {
    if (forced) return;
    const onStorage = (e: StorageEvent) => {
      if (e.key === KEY) setState(isVariant(e.newValue) ? e.newValue : 'auto');
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [forced]);

  const setChoice = useCallback((c: ComposerChoice) => {
    setState(c);
    storage.set(KEY, c);
  }, []);

  const value = useMemo(() => ({ choice, setChoice }), [choice, setChoice]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useComposerChoice = () => useContext(Ctx);

/** The variant a composer should render: the global pick, or the template's own default under `auto`. */
export function useComposerVariant(fallback: ComposerVariant = 'pill'): ComposerVariant {
  const { choice } = useContext(Ctx);
  return choice === 'auto' ? fallback : choice;
}

// localStorage can throw (private windows, blocked site data): every access goes through here.
export const storage = {
  get(key: string, fallback: string): string {
    try {
      return localStorage.getItem(key) ?? fallback;
    } catch {
      return fallback;
    }
  },
  set(key: string, value: string) {
    try {
      localStorage.setItem(key, value);
    } catch {
      /* not persisted */
    }
  },
};

export const STORAGE_KEYS = { theme: 'sui-theme', palette: 'sui-palette', view: 'sr-view' } as const;
